/* Birdbird – humanperf.js: the Human performance lab (humanperf.html).
   One dark figure with three modes: workload against capacity through a flight (with weather, a late runway change, startle,
   hand-flying, early briefing and fatigue), the alertness day (sleep, the body clock, the duty period and the alcohol comparison),
   and the threat-and-error chain with countermeasures. Maths in hfcore.js (HFC). */
(function(){
'use strict';
const {L,el,nf}=LAB, H=HFC, t2=(en,no)=>({en,no});
const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
const MONO='"IBM Plex Mono", ui-monospace, monospace', SANS='"Public Sans", system-ui, sans-serif';
const C={dem:'#F0C470',cap:'#71CC93',txt:'#EEF2F5',mut:'#8E99A4',dim:'#5E6D7C',red:'#EC5A47',ok:'#71CC93',amb:'#F0C470',blue:'#7FCBE8',vio:'#C9B6F2',grid:'rgba(200,215,225,.10)'};
const clamp=H.clamp;
const depth=()=>document.body.classList.contains('depth-short')?'short':document.body.classList.contains('depth-instructor')?'instructor':'deep';
const deepOn=()=>depth()!=='short';
const hh=h=>String(Math.floor(((h%24)+24)%24)).padStart(2,'0')+':'+String(Math.round((((h%1)+1)%1)*60)%60).padStart(2,'0');

/* ---------------- state ---------------- */
const S={mode:'wl',wx:'good',brief:false,hand:false,change:false,startle:false,fatigue:0,bed:23,sleep:8,debt:0,report:8,len:10,sc:'rwy',cm:{brief:false,sop:false,cross:false,speak:false}};
const WL=()=>H.workload({wx:S.wx,brief:S.brief,hand:S.hand,change:S.change,startle:S.startle,fatigue:+S.fatigue});
const DAY=()=>H.day({bed:S.bed,sleep:S.sleep,debt:S.debt,report:S.report,len:S.len});

/* ---------------- canvas helpers ---------------- */
const cv=el('hpv'); const ST=LAB.fit(cv,()=>draw(),2);
let FS=1;
function txt(g,s,x,y,col,al,sz,wt,font){ g.font=`${wt||500} ${Math.round((sz||12)*FS*10)/10}px ${font||MONO}`; g.fillStyle=col||C.txt; g.textAlign=al||'left'; g.textBaseline='alphabetic'; g.fillText(s,x,y); g.textAlign='left'; }
function line(g,x1,y1,x2,y2,col,w,dash){ g.strokeStyle=col; g.lineWidth=w||1; g.setLineDash(dash||[]); g.beginPath(); g.moveTo(x1,y1); g.lineTo(x2,y2); g.stroke(); g.setLineDash([]); }
function poly(g,pts,col,w,dash){ g.strokeStyle=col; g.lineWidth=w||1; g.setLineDash(dash||[]); g.beginPath(); pts.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y)); g.stroke(); g.setLineDash([]); }
function dot(g,x,y,r,fill,stroke,w){ g.beginPath(); g.arc(x,y,r,0,Math.PI*2); if(fill){ g.fillStyle=fill; g.fill(); } if(stroke){ g.strokeStyle=stroke; g.lineWidth=w||1.5; g.stroke(); } }
function rr(g,x,y,w,h,r){ g.beginPath(); g.roundRect?g.roundRect(x,y,w,h,r):g.rect(x,y,w,h); }
function tag(g,s,x,y,col,o){ o=o||{}; const sz=(o.sz||11.5)*FS; g.font=`${o.wt||600} ${sz}px ${o.font||SANS}`; const w=g.measureText(s).width+10, h=sz+7;
  let bx=o.al==='right'?x-w:o.al==='center'?x-w/2:x; bx=clamp(bx,2,ST.w-w-2); const by=y-h/2;
  if(o.bg!==false){ g.fillStyle='rgba(10,14,18,.85)'; rr(g,bx,by,w,h,3); g.fill(); }
  g.fillStyle=col||C.txt; g.textBaseline='middle'; g.textAlign='left'; g.fillText(s,bx+5,y+0.5); g.textBaseline='alphabetic'; return [bx,by,bx+w,by+h]; }
function chipLeft(){ const chip=el('chip'); if(ST.w<640||!chip||getComputedStyle(chip).position!=='absolute'||!chip.offsetWidth) return 0; return chip.offsetLeft+chip.offsetWidth+10; }

/* ---------------- the figure ---------------- */
function draw(){ if(!ST.w||S.mode==='tem') return; const g=ST.ctx, W=ST.w, Hh=ST.h; g.setTransform(ST.dpr,0,0,ST.dpr,0,0); g.clearRect(0,0,W,Hh);
  FS=depth()==='instructor'?1.15:W<420?0.9:1;
  if(S.mode==='wl') drawWl(g,W,Hh); else drawFat(g,W,Hh); }

const PHN={pre:t2('Pre-flight','Før flyging'),taxi:t2('Taxi','Taksing'),to:t2('Take-off','Start'),climb:t2('Climb','Stigning'),cruise:t2('Cruise','Marsj'),desc:t2('Descent','Nedstigning'),app:t2('Approach','Innflyging'),ldg:t2('Landing','Landing')};
const PHS={pre:t2('Pre','Før'),taxi:t2('Taxi','Taks'),to:t2('T/O','Start'),climb:t2('Clb','Stig'),cruise:t2('Cruise','Marsj'),desc:t2('Desc','Ned'),app:t2('App','Innfl'),ldg:t2('Ldg','Land')};
function drawWl(g,W,Hh){ const R=WL(), ph=W<640, cl=chipLeft(), d=deepOn()&&!ph;
  const x0=ph?8:Math.max(cl,12), w=(d?(W-x0)*0.7:W-x0)-12, y0=10, h=Hh-20;
  g.fillStyle='rgba(6,9,12,.35)'; rr(g,x0,y0,w,h,6); g.fill();
  const pl=x0+(ph?30:40), pr=x0+w-10, pt=y0+(ph?26:30), pb=y0+h-(ph?30:34), X=x=>pl+x/100*(pr-pl), Y=v=>pb-v/110*(pb-pt);
  txt(g,L(t2('DEMAND ON YOUR ATTENTION THROUGH A FLIGHT','KRAV TIL OPPMERKSOMHETEN GJENNOM EN FLYGING')),x0+10,y0+16,'#AEB8C1','left',ph?9:10.5,600);
  /* phases */
  R.phases.forEach(([k,a,b],i)=>{ if(i%2) { g.fillStyle='rgba(255,255,255,.025)'; g.fillRect(X(a),pt,X(b)-X(a),pb-pt); } txt(g,L((ph||(b-a)<9)?PHS[k]:PHN[k]),(X(a)+X(b))/2,pb+14,C.mut,'center',ph?8.5:10,500,SANS); });
  for(let v=0;v<=100;v+=25){ line(g,pl,Y(v),pr,Y(v),C.grid,1); txt(g,String(v),pl-5,Y(v)+3.5,C.dim,'right',9); }
  /* underload band */
  g.fillStyle='rgba(127,203,232,.07)'; g.fillRect(pl,Y(25),pr-pl,pb-Y(25)); txt(g,L(t2('underload: vigilance drops','underbelastning: årvåkenheten faller')),pr-6,Y(25)+13,'rgba(127,203,232,.8)','right',ph?8.5:9.5,500,SANS);
  /* demand area */
  const rows=R.rows; g.beginPath(); g.moveTo(X(0),Y(0)); rows.forEach(r=>g.lineTo(X(r.x),Y(r.d))); g.lineTo(X(100),Y(0)); g.closePath(); g.fillStyle='rgba(240,196,112,.16)'; g.fill();
  /* overload: where demand > capacity */
  g.save(); g.beginPath(); rows.forEach((r,i)=>i?g.lineTo(X(r.x),Y(r.cap)):g.moveTo(X(r.x),Y(r.cap))); g.lineTo(X(100),pt); g.lineTo(X(0),pt); g.closePath(); g.clip();
  g.beginPath(); g.moveTo(X(0),Y(0)); rows.forEach(r=>g.lineTo(X(r.x),Y(r.d))); g.lineTo(X(100),Y(0)); g.closePath(); g.fillStyle='rgba(236,90,71,.55)'; g.fill(); g.restore();
  poly(g,rows.map(r=>[X(r.x),Y(r.d)]),C.dem,2.2); poly(g,rows.map(r=>[X(r.x),Y(r.cap)]),C.cap,2.2,[7,4]);
  txt(g,L(t2('your capacity','kapasiteten din')),X(36),Y(rows[144].cap)-6,C.cap,'left',ph?9:10.5,600,SANS);
  const ov=rows.filter(r=>r.d>r.cap); if(ov.length){ const m=ov.reduce((a,b)=>b.d-b.cap>a.d-a.cap?b:a); tag(g,L(t2('overload: tunnelling, missed items, errors','overbelastning: tunnelsyn, glemte punkter, feil')),X(m.x),Math.max(pt+10,Y(m.d)-14),C.red,{al:m.x>60?'right':'center',sz:ph?9.5:11}); }
  if(S.startle) tag(g,L(t2('startle','skvettreaksjon')),X(81),Y(Math.min(100,rows[324].d))-4,C.red,{al:'center',sz:ph?9:10,bg:false});
  if(S.brief) tag(g,L(t2('plan and brief here','planlegg og brief her')),X(52),Y(rows[208].d)-24,C.dem,{al:'center',sz:ph?9:10,bg:false});
  if(d) drawYd(g,[x0+w+12,y0,W-x0-w-24,h],R); }
/* the inverted U: where each phase sits on the arousal curve */
function drawYd(g,b,R){ const [x0,y0,w,h]=b; g.fillStyle='rgba(6,9,12,.35)'; rr(g,x0,y0,w,h,6); g.fill();
  const pl=x0+14, pr=x0+w-12, pt=y0+46, pb=y0+h*0.7, X=x=>pl+x*(pr-pl), Y=v=>pb-v*(pb-pt);
  txt(g,L(t2('AROUSAL AND PERFORMANCE','AKTIVERING OG PRESTASJON')),x0+10,y0+16,'#AEB8C1','left',10,600); txt(g,L(t2('the inverted U','den omvendte U-en')),x0+10,y0+31,C.dim,'left',9.5,500,SANS);
  const pts=[]; for(let i=0;i<=60;i++){ const x=i/60; pts.push([X(x),Y(H.yd(x))]); } poly(g,pts,C.txt,2);
  line(g,pl,pb,pr,pb,'rgba(214,226,236,.3)',1); txt(g,L(t2('low','lav')),pl,pb+13,C.dim,'left',9); txt(g,L(t2('high','høy')),pr,pb+13,C.dim,'right',9); txt(g,L(t2('arousal →','aktivering →')),(pl+pr)/2,pb+13,C.dim,'center',9);
  const ax=x=>clamp(x,0.03,0.98); const pick=k=>R.rows.filter(r=>r.ph===k), avg=a=>a.reduce((s,r)=>s+r.d/r.cap,0)/a.length;
  const pts2=[['cruise',C.blue],['app',C.dem]].map(([k,c])=>[k,c,ax(avg(pick(k))*0.75)]);
  const mx=R.rows.reduce((a,r)=>r.d/r.cap>a.d/a.cap?r:a); pts2.push(['peak',mx.d>mx.cap?C.red:C.amb,ax(mx.d/mx.cap*0.75)]);
  let ly=pb+30; for(const [k,c,x] of pts2){ dot(g,X(x),Y(H.yd(x)),5,c); txt(g,k==='peak'?L(t2('● busiest moment','● travleste øyeblikk')):'● '+L(PHN[k]),pl,ly,c,'left',10,600,SANS); ly+=16; } }

function drawFat(g,W,Hh){ const D=DAY(), ph=W<640, cl=chipLeft();
  const x0=ph?8:Math.max(cl,12), w=W-x0-12, y0=10, h=Hh-20;
  g.fillStyle='rgba(6,9,12,.35)'; rr(g,x0,y0,w,h,6); g.fill();
  const t0=D.rows[0].t, t1=D.rows[D.rows.length-1].t, pl=x0+(ph?30:40), pr=x0+w-10, pt=y0+(ph?28:32), pb=y0+h-(ph?48:54);
  const X=t=>pl+(t-t0)/(t1-t0)*(pr-pl), Y=v=>pb-v*(pb-pt);
  txt(g,L(t2('YOUR ALERTNESS (teaching model)','ÅRVÅKENHETEN DIN (undervisningsmodell)')),x0+10,y0+16,'#AEB8C1','left',ph?9:10.5,600);
  /* zones */
  const zb=[[0.5,1,'rgba(113,204,147,.06)',t2('alert','våken')],[0.3,0.5,'rgba(240,196,112,.08)',t2('reduced','redusert')],[0,0.3,'rgba(236,90,71,.10)',t2('high risk','høy risiko')]];
  for(const [a,b,c,lab] of zb){ g.fillStyle=c; g.fillRect(pl,Y(b),pr-pl,Y(a)-Y(b)); txt(g,L(lab),pl+4,Y(b)+12,C.dim,'left',ph?8.5:9.5,500,SANS); }
  /* WOCL bands */
  for(let k=Math.floor(t0/24)*24;k<t1;k+=24){ const a=Math.max(t0,k+2), b=Math.min(t1,k+6); if(b>a){ g.fillStyle='rgba(127,203,232,.10)'; g.fillRect(X(a),pt,X(b)-X(a),pb-pt); txt(g,'WOCL',(X(a)+X(b))/2,pt+11,C.blue,'center',ph?8:9.5,600); } }
  /* clock ticks */
  for(let t=Math.ceil(t0/3)*3;t<=t1;t+=3){ line(g,X(t),pb,X(t),pb+4,C.dim,1); if(!ph||t%6===0) txt(g,hh(t),X(t),pb+15,C.dim,'center',9); }
  /* sleep block */
  g.fillStyle='rgba(201,182,242,.18)'; g.fillRect(X(t0),pt,X(D.wake)-X(t0),pb-pt); txt(g,L(t2('sleep ','søvn '))+nf(S.sleep,0)+' h',(X(t0)+X(D.wake))/2,pb-8,C.vio,'center',ph?8.5:10,600,SANS);
  /* duty bar */
  const by=pb+(ph?24:26); g.fillStyle='rgba(240,196,112,.85)'; rr(g,X(D.rep),by,X(D.end)-X(D.rep),ph?8:10,3); g.fill();
  txt(g,L(t2('duty ','tjeneste '))+hh(D.rep)+'–'+hh(D.end),(X(D.rep)+X(D.end))/2,by+(ph?20:24),C.amb,'center',ph?9:10,600,SANS);
  g.fillStyle='rgba(240,196,112,.06)'; g.fillRect(X(D.rep),pt,X(D.end)-X(D.rep),pb-pt);
  /* the alertness curve */
  const aw=D.rows.filter(r=>!r.asleep); poly(g,aw.map(r=>[X(r.t),Y(r.A)]),C.txt,2.2);
  const dutyRows=aw.filter(r=>r.onDuty); if(dutyRows.length) poly(g,dutyRows.map(r=>[X(r.t),Y(r.A)]),C.dem,3);
  /* the low point on duty */
  const z=H.zone(D.minA), zc=z==='ok'?C.ok:z==='low'?C.amb:C.red; dot(g,X(D.minAt),Y(D.minA),5.5,'#0c1217',zc,2.4);
  tag(g,L(t2('lowest on duty ','lavest i tjeneste '))+hh(D.minAt),X(D.minAt),Y(D.minA)+(D.minA>0.2?18:-18),zc,{al:X(D.minAt)>pr-90?'right':X(D.minAt)<pl+90?'left':'center',sz:ph?9.5:11}); }

/* ---------------- the threat-and-error chain ---------------- */
const CMN={brief:t2('Plan and brief','Planlegg og brief'),sop:t2('SOPs and checklists','SOP-er og sjekklister'),cross:t2('Monitor and crosscheck','Overvåk og kryssjekk'),speak:t2('Speak up','Si fra')};
const STG=[t2('Threat','Trussel'),t2('Error','Feil'),t2('Undesired aircraft state','Uønsket flytilstand'),t2('Outcome','Utfall')];
const SCEN={
 rwy:{t:t2('Late runway change','Sen rullebaneendring'),s:[t2('ATC changes the runway during the descent: shorter, with a tailwind, and you are already close in.','ATC endrer rullebanen under nedstigningen: kortere, med medvind, og dere er allerede nære.'),t2('The new approach is set up in a hurry and not briefed; the speed stays high.','Den nye innflygingen settes opp i full fart og briefes ikke; farten blir liggende høy.'),t2('At 1 000 ft the aircraft is high, fast and not fully configured: unstable.','I 1 000 ft er flyet høyt, raskt og ikke ferdig konfigurert: ustabilt.'),t2('A long, fast landing on a short wet runway: runway excursion.','En lang og rask landing på en kort, våt rullebane: utforkjøring.')],
  c:{brief:[0,t2('Ask for time (a vector or a hold), set up and brief the new approach. The threat is managed before it causes an error.','Be om tid (en vektor eller en holding), sett opp og brief den nye innflygingen. Trusselen håndteres før den gir en feil.')],
     cross:[1,t2('The pilot monitoring crosschecks the FMS, the speed and the descent against the new approach and calls it. The error is trapped.','Den monitorerende piloten kryssjekker FMS, fart og nedstigning mot den nye innflygingen og sier fra. Feilen fanges.')],
     sop:[2,t2('Stabilised approach criteria: not stable at 1 000 ft, go around. The aircraft state is recovered.','Kriterier for stabilisert innflyging: ikke stabil i 1 000 ft, gå rundt. Flytilstanden gjenopprettes.')],
     speak:[2,t2('"We are not stable. Go around." The pilot flying goes around.','«Vi er ikke stabile. Go around.» Den flygende piloten går rundt.')]}},
 alt:{t:t2('Wrong altitude set','Feil høyde satt'),s:[t2('A busy frequency, a similar call sign, and the climb clearance comes in the middle of a checklist.','En travel frekvens, et lignende kallesignal, og stigningsklareringen kommer midt i en sjekkliste.'),t2('The crew sets 7 000 ft instead of the cleared 6 000 ft.','Besetningen setter 7 000 ft i stedet for klarerte 6 000 ft.'),t2('The aircraft climbs through 6 000 ft towards traffic at 7 000 ft.','Flyet stiger gjennom 6 000 ft mot trafikk i 7 000 ft.'),t2('A level bust: loss of separation and a TCAS resolution advisory.','Et nivåbrudd: tap av separasjon og en TCAS RA.')],
  c:{brief:[0,t2('Manage the workload: pause the checklist while ATC is talking, and expect the clearance from the departure brief.','Styr arbeidsmengden: stopp sjekklisten mens ATC snakker, og forvent klareringen fra avgangsbriefen.')],
     cross:[1,t2('Read back, and both pilots point at and confirm the altitude set against the clearance. The error is trapped.','Les tilbake, og begge piloter peker på og bekrefter høyden som er satt mot klareringen. Feilen fanges.')],
     speak:[1,t2('"Confirm we were cleared to 6 000?" One question to ATC traps the error.','«Bekreft at vi ble klarert til 6 000?» Ett spørsmål til ATC fanger feilen.')],
     sop:[2,t2('The "1 000 to go" callout and the level-off check catch the climb past the cleared level. The state is recovered early.','«1 000 igjen»-utropet og sjekken ved utflating fanger stigningen forbi klarert nivå. Tilstanden gjenopprettes tidlig.')]}},
 wx:{t:t2('Weather and fuel','Vær og drivstoff'),s:[t2('The destination weather is worse than forecast and the fuel is getting close to the planned diversion fuel.','Været på destinasjonen er verre enn varslet, og drivstoffet nærmer seg planlagt alternativdrivstoff.'),t2('One more approach, and then one more: the crew presses on instead of deciding (plan continuation bias).','Én innflyging til, og så én til: besetningen fortsetter i stedet for å bestemme seg (plan continuation bias).'),t2('After the second missed approach the fuel is below what is needed to reach the alternate.','Etter den andre avbrutte innflygingen er drivstoffet under det som trengs for å nå alternativ flyplass.'),t2('A fuel emergency and a forced landing in poor weather.','En drivstoffnødsituasjon og en tvungen landing i dårlig vær.')],
  c:{brief:[0,t2('Decide early with a model (for example FOR-DEC or DODAR): set a decision point and a fuel figure to divert at, before the first approach.','Bestem tidlig med en modell (for eksempel FOR-DEC eller DODAR): sett et beslutningspunkt og et drivstofftall for å dra til alternativ før første innflyging.')],
     sop:[1,t2('The fuel policy says divert at the decision fuel. Following it traps the error of "one more try".','Drivstoffpolicyen sier: dra til alternativ ved beslutningsdrivstoffet. Å følge den fanger feilen «ett forsøk til».')],
     speak:[1,t2('"We are at diversion fuel. I suggest we divert now." The crew diverts.','«Vi er på alternativdrivstoff. Jeg foreslår at vi drar dit nå.» Besetningen drar til alternativ.')],
     cross:[2,t2('A fuel check after the missed approach shows the problem, and the crew declares MAYDAY FUEL to get priority: the outcome is mitigated, not prevented.','En drivstoffsjekk etter den avbrutte innflygingen viser problemet, og besetningen erklærer MAYDAY FUEL for å få prioritet: utfallet dempes, men forhindres ikke.')]}}};
function temState(){ const sc=SCEN[S.sc]; let trap=null; for(const [k,on] of Object.entries(S.cm)) if(on&&sc.c[k]&&(trap==null||sc.c[k][0]<sc.c[trap][0])) trap=k; return {sc,trap,stage:trap?sc.c[trap][0]:4}; }
function drawTem(){ const T=temState(), sc=T.sc;
  const n=Object.values(S.cm).filter(Boolean).length;
  let h=`<p class="tq">${L(sc.t)}</p><p class="tstat"><span>${L(t2('Stopped at','Stoppet ved'))}: <b class="${T.trap?(T.stage===0?'g':'a'):'r'}">${T.trap?L(STG[T.stage]):L(t2('not stopped','ikke stoppet'))}</b></span><span>${L(t2('Countermeasures on','Mottiltak på'))}: <b>${n}</b></span></p><div class="chain">`;
  STG.forEach((st,i)=>{ const reached=i<=T.stage, trapped=T.trap&&i===T.stage, bad=!T.trap&&i===3;
    h+=`<div class="st ${trapped?'trap':bad?'bad':reached?'hit':'off'}"><span class="k">${i+1} · ${L(st)}</span><p>${L(sc.s[i])}</p>${trapped?`<span class="badge">✓ ${L(t2('Stopped here by','Stoppet her av'))}: ${L(CMN[T.trap])}</span>`:bad?`<span class="badge r">${L(t2('Nothing stopped the chain.','Ingenting stoppet kjeden.'))}</span>`:''}</div>`; });
  h+=`</div><ul class="cms">${Object.keys(CMN).map(k=>`<li class="${S.cm[k]?'on':''}"><b>${L(CMN[k])}</b> (${L(STG[sc.c[k][0]])}): ${L(sc.c[k][1])}</li>`).join('')}</ul>`;
  el('temBox').innerHTML=h; }

/* ---------------- readout chip, legend, "what you're seeing" ---------------- */
const ch=(i,b,cls)=>`<span><i>${i}</i><b${cls?` class="${cls}"`:''}>${b}</b></span>`;
function readout(){ let h='';
  if(S.mode==='wl'){ const R=WL(); h=ch(L(t2('Lowest spare capacity','Minst ledig kapasitet')),Math.round(R.minSpare)+' %',R.minSpare<0?'r':R.minSpare<10?'a':'g')+ch(L(t2('Overloaded','Overbelastet')),R.over>0?Math.round(R.over)+' % '+L(t2('of the flight','av flygingen')):L(t2('never','aldri')),R.over>0?'r':'g')+ch(L(t2('Underloaded','Underbelastet')),Math.round(R.under)+' %',R.under>15?'a':''); }
  else if(S.mode==='fat'){ const D=DAY(), z=H.zone(D.minA); h=ch(L(t2('Lowest on duty','Lavest i tjeneste')),L(z==='ok'?t2('alert','våken'):z==='low'?t2('reduced','redusert'):t2('high risk','høy risiko'))+' · '+hh(D.minAt),z==='ok'?'g':z==='low'?'a':'r')+ch(L(t2('Awake at the end','Våken ved slutt')),nf(D.awakeEnd,0)+' h',D.awakeEnd>=17?'r':D.awakeEnd>=14?'a':'')+ch(L(t2('Like blood alcohol (typical)','Som promille (typisk)')),D.awakeEnd<14?'—':'≈ '+nf(D.bac*10,1)+' ‰',D.bac>=0.05?'r':D.bac>0.02?'a':'')+ch(L(t2('Duty in the WOCL','Tjeneste i WOCL')),nf(D.wocl,1)+' h',D.wocl>=2?'a':''); }
  else { const T=temState(); h=ch(L(t2('Stopped at','Stoppet ved')),T.trap?L(STG[T.stage]):L(t2('not stopped','ikke stoppet')),T.trap?(T.stage===0?'g':'a'):'r')+ch(L(t2('Countermeasures on','Mottiltak på')),String(Object.values(S.cm).filter(Boolean).length)); }
  el('chip').innerHTML=h; const v=VIEWS.find(v=>v[0]===S.mode); el('xsv').textContent=v?L(v[1]):''; }
function legend(){ const lg=(c,t,k)=>`<span><i class="${k||''}" style="--c:${c}"></i>${L(t)}</span>`; let s='';
  if(S.mode==='wl') s=lg(C.dem,t2('demand (the task)','krav (oppgaven)'),'ln')+lg(C.cap,t2('your capacity','kapasiteten din'),'ln')+lg(C.red,t2('overload','overbelastning'),'sq')+lg(C.blue,t2('underload','underbelastning'),'sq');
  else if(S.mode==='fat') s=lg(C.txt,t2('alertness','årvåkenhet'),'ln')+lg(C.dem,t2('on duty','i tjeneste'),'ln')+lg(C.vio,t2('sleep','søvn'),'sq')+lg(C.blue,t2('window of circadian low, 02–06','døgnrytmens bunn, 02–06'),'sq');
  else s=lg(C.amb,t2('the chain goes on','kjeden fortsetter'),'sq')+lg(C.ok,t2('stopped by a countermeasure','stoppet av et mottiltak'),'sq')+lg(C.red,t2('accident or incident','ulykke eller hendelse'),'sq');
  el('vleg').innerHTML=s; }
function see(){ let t;
  if(S.mode==='wl'){ const R=WL();
    t= S.startle? t2('<b>Startle:</b> a sudden bang on short final. Demand jumps and, for several seconds, your capacity drops: thinking slows and attention narrows. Fly the aircraft first, then work out what happened.','<b>Skvettreaksjon:</b> et plutselig smell på kort finale. Kravet hopper, og i flere sekunder faller kapasiteten: tenkningen går tregere og oppmerksomheten snevres inn. Fly flyet først, finn ut hva som skjedde etterpå.')
     : R.over>0? t2('<b>Demand exceeds capacity.</b> Something has to give: you tunnel on one thing, skip items and make errors. Move work to the quiet phases (brief early), use the automation well, or reduce the task (ask for time, a hold, a longer final).','<b>Kravet er større enn kapasiteten.</b> Noe må vike: du får tunnelsyn, hopper over punkter og gjør feil. Flytt arbeid til de rolige fasene (brief tidlig), bruk automatikken godt, eller reduser oppgaven (be om tid, en holding, en lengre finale).')
     : S.brief? t2('<b>Briefing early</b> moves work from the approach, where you are busiest, to the cruise, where you have time. The peak drops and there is spare capacity for the unexpected.','<b>Tidlig brief</b> flytter arbeid fra innflygingen, der du har mest å gjøre, til marsjen, der du har tid. Toppen synker, og det blir ledig kapasitet til det uventede.')
     : t2('<b>Workload peaks at take-off and on the approach</b>, and is very low in the cruise. Too low is a risk too: attention wanders and monitoring suffers. Make a change and watch the margin.','<b>Arbeidsbelastningen topper seg ved start og på innflygingen</b>, og er svært lav i marsjen. For lav er også en risiko: oppmerksomheten vandrer og overvåkingen svikter. Gjør en endring og se på marginen.'); }
  else if(S.mode==='fat'){ const D=DAY(), z=H.zone(D.minA);
    t= z==='high'? t2(`<b>High risk at ${hh(D.minAt)}:</b> ${nf(D.awakeEnd,0)} h awake by the end of the duty${D.wocl>0?', and through the window of circadian low':''}. Performance is comparable to a blood alcohol of about ${nf(D.bac*10,1)} ‰ (typical). Sleep before the duty, or the duty should not be flown as planned.`,`<b>Høy risiko kl. ${hh(D.minAt)}:</b> ${nf(D.awakeEnd,0)} t våken ved slutten av tjenesten${D.wocl>0?', og gjennom døgnrytmens bunn':''}. Prestasjonen kan sammenlignes med rundt ${nf(D.bac*10,1)} ‰ promille (typisk). Sov før tjenesten, ellers bør den ikke flys som planlagt.`)
     : z==='low'? t2(`<b>Reduced alertness at ${hh(D.minAt)}.</b> Two things wear you down: hours awake (sleep pressure) and the body clock, lowest around 02–06. Plan the critical tasks, use the crew, and report fatigue if you are not fit.`,`<b>Redusert årvåkenhet kl. ${hh(D.minAt)}.</b> To ting sliter deg ned: timer våken (søvnpress) og døgnrytmen, lavest rundt 02–06. Planlegg de kritiske oppgavene, bruk besetningen, og meld tretthet hvis du ikke er skikket.`)
     : t2('<b>Alert through the duty:</b> a full night of sleep, a day duty, no work in the window of circadian low. Now move the report to 22:00 and see what the body clock does.','<b>Våken gjennom tjenesten:</b> en full natts søvn, dagtjeneste, ikke arbeid i døgnrytmens bunn. Flytt oppmøtet til 22:00 og se hva døgnrytmen gjør.'); }
  else { const T=temState();
    t= !T.trap? t2('<b>Threat and error management:</b> a threat (outside the crew) leads to an error (by the crew), the error to an undesired aircraft state, and that to the outcome. Switch on countermeasures and see where each one stops the chain.','<b>Trussel- og feilhåndtering:</b> en trussel (utenfor besetningen) fører til en feil (av besetningen), feilen til en uønsket flytilstand, og den til utfallet. Slå på mottiltak og se hvor hvert av dem stopper kjeden.')
     : T.stage===0? t2('<b>Managed at the threat:</b> the best place. Nothing went wrong, so there was nothing to fix.','<b>Håndtert ved trusselen:</b> det beste stedet. Ingenting gikk galt, så det var ingenting å rette opp.')
     : T.stage===1? t2('<b>Trapped at the error:</b> it happened, but was caught before the aircraft was affected.','<b>Fanget ved feilen:</b> den skjedde, men ble fanget før flyet ble påvirket.')
     : t2('<b>Recovered from the undesired aircraft state:</b> the last line of defence. Fly the aircraft first, then fix the error.','<b>Gjenopprettet fra den uønskede flytilstanden:</b> siste forsvarslinje. Fly flyet først, rett opp feilen etterpå.'); }
  el('xsee').innerHTML=L(t); }

/* ---------------- tabs ---------------- */
const VIEWS=[['wl',t2('Workload and attention','Arbeidsbelastning og oppmerksomhet')],['fat',t2('Fatigue and the body clock','Tretthet og døgnrytme')],['tem',t2('Threat and error','Trussel og feil')]];
function drawTabs(){ el('vtabs').innerHTML=VIEWS.map(([k,t])=>`<button type="button" role="tab" data-v="${k}" class="${k===S.mode?'on':''}" aria-selected="${k===S.mode}">${L(t)}</button>`).join(''); }
el('vtabs').addEventListener('click',e=>{ const b=e.target.closest('button'); if(b) setMode(b.dataset.v); });
function setMode(m){ if(!VIEWS.some(v=>v[0]===m)) m='wl'; S.mode=m; el('xpanel').querySelectorAll('[data-pv]').forEach(d=>{ d.hidden=!d.dataset.pv.split(' ').includes(m); });
  cv.hidden=m==='tem'; el('temBox').hidden=m!=='tem'; el('chip').hidden=m==='tem'; drawTabs(); drawPre(); syncCtl(); upd(); }

/* ---------------- controls ---------------- */
LAB.add({},{'Good weather':'Godt vær','Poor weather':'Dårlig vær','Rested':'Uthvilt','Tired':'Trøtt','Very tired':'Svært trøtt','Bedtime':'Leggetid','Sleep':'Søvn','Nights of short sleep before':'Netter med lite søvn før','Report time':'Oppmøte','Duty length':'Tjenestelengde'});
const chkBox=(box,items)=>{ el(box).innerHTML=items.map(([k,t])=>`<label class="chk"><input type="checkbox" data-k="${k}"> <span data-t="${k}"></span></label>`).join(''); };
const WLCHK=[['change',t2('Late runway change','Sen rullebaneendring')],['startle',t2('Startle on short final','Skvettreaksjon på kort finale')],['hand',t2('Hand-fly, autopilot off','Håndfly, autopilot av')],['brief',t2('Plan and brief early','Planlegg og brief tidlig')]];
chkBox('wlChk',WLCHK); chkBox('temChk',Object.entries(CMN));
el('wlChk').addEventListener('change',e=>{ const i=e.target.closest('input'); if(!i) return; S[i.dataset.k]=i.checked; upd(); });
el('temChk').addEventListener('change',e=>{ const i=e.target.closest('input'); if(!i) return; S.cm[i.dataset.k]=i.checked; upd(); });
const wxSeg=LAB.seg(el('wxSeg'),[['good','Good weather'],['poor','Poor weather']],S.wx,v=>{ S.wx=v; upd(); });
const fatSeg=LAB.seg(el('fatSeg'),[['0','Rested'],['1','Tired'],['2','Very tired']],String(S.fatigue),v=>{ S.fatigue=+v; upd(); });
const temSeg=LAB.seg(el('temSeg'),Object.entries(SCEN).map(([k,o])=>[k,o.t.en]),S.sc,v=>{ S.sc=v; upd(); });
LAB.add({},Object.fromEntries(Object.values(SCEN).map(o=>[o.t.en,o.t.no])));
el('temSeg').classList.add('wrap');
const sl={};
sl.bed=LAB.slider(el('slCtl'),{label:'Bedtime',min:0,max:23.5,step:0.5,v:S.bed,f:v=>hh(v),on:v=>{ S.bed=v; upd(); }});
sl.sleep=LAB.slider(el('slCtl'),{label:'Sleep',min:3,max:10,step:0.5,v:S.sleep,f:v=>nf(v,1)+' h',on:v=>{ S.sleep=v; upd(); }});
sl.debt=LAB.slider(el('slCtl'),{label:'Nights of short sleep before',min:0,max:4,step:1,v:S.debt,f:v=>String(v),on:v=>{ S.debt=v; upd(); }});
sl.report=LAB.slider(el('dtCtl'),{label:'Report time',min:0,max:23.5,step:0.5,v:S.report,f:v=>hh(v),on:v=>{ S.report=v; upd(); }});
sl.len=LAB.slider(el('dtCtl'),{label:'Duty length',min:3,max:14,step:0.5,v:S.len,f:v=>nf(v,1)+' h',on:v=>{ S.len=v; upd(); }});
function syncCtl(){ wxSeg.set(S.wx); fatSeg.set(String(S.fatigue)); temSeg.set(S.sc); ['bed','sleep','debt','report','len'].forEach(k=>sl[k].set(S[k]));
  el('wlChk').querySelectorAll('input').forEach(i=>{ i.checked=!!S[i.dataset.k]; }); el('temChk').querySelectorAll('input').forEach(i=>{ i.checked=!!S.cm[i.dataset.k]; });
  [...el('wlChk').querySelectorAll('[data-t]'),...el('temChk').querySelectorAll('[data-t]')].forEach(s=>{ const it=WLCHK.find(x=>x[0]===s.dataset.t)||[0,CMN[s.dataset.t]]; s.textContent=L(it[1]); }); }

/* scenarios per mode */
const WL0={wx:'good',brief:false,hand:false,change:false,startle:false,fatigue:0}, CM0={brief:false,sop:false,cross:false,speak:false};
const SCN={
 wl:[[t2('A normal flight','En vanlig flyging'),{...WL0}],[t2('Poor weather and a late runway change','Dårlig vær og sen rullebaneendring'),{...WL0,wx:'poor',change:true}],[t2('The same, briefed early','Det samme, brifet tidlig'),{...WL0,wx:'poor',change:true,brief:true}],[t2('Startle on short final','Skvettreaksjon på kort finale'),{...WL0,startle:true}],[t2('Very tired, poor weather','Svært trøtt, dårlig vær'),{...WL0,wx:'poor',fatigue:2}]],
 fat:[[t2('Day duty after a good night','Dagtjeneste etter en god natt'),{bed:23,sleep:8,debt:0,report:8,len:10}],[t2('Early start','Tidlig start'),{bed:22,sleep:6,debt:0,report:5,len:10}],[t2('Night duty, no sleep before','Nattjeneste, ingen søvn før'),{bed:23,sleep:8,debt:0,report:22,len:10}],[t2('Night duty, afternoon sleep','Nattjeneste, søvn på ettermiddagen'),{bed:13,sleep:6,debt:0,report:22,len:10}],[t2('A week of short nights','En uke med korte netter'),{bed:0,sleep:5,debt:4,report:8,len:12}]],
 tem:[[t2('No countermeasures','Ingen mottiltak'),{cm:{...CM0}}],[t2('Only the last line of defence','Bare siste forsvarslinje'),{cm:{...CM0,sop:true}}],[t2('All four','Alle fire'),{cm:{brief:true,sop:true,cross:true,speak:true}}]]};
function drawPre(){ el('pre').innerHTML=(SCN[S.mode]||[]).map(([t],i)=>`<button type="button" class="btn" data-s="${i}">${L(t)}</button>`).join(''); }
el('pre').addEventListener('click',e=>{ const b=e.target.closest('button'); if(b) setS(Object.assign({mode:S.mode},SCN[S.mode][+b.dataset.s][1])); });
function setS(o){ if(!o) return; const {mode,cm,...r}=o; if(mode&&mode!==S.mode) setMode(mode); Object.assign(S,r); if(cm) S.cm={...cm}; syncCtl(); upd(); }
function upd(){ readout(); legend(); see(); if(S.mode==='tem') drawTem(); else draw(); }

/* ---------------- Try it: one task at a time ---------------- */
let ti=0; const ansv={}, done={};
const goModel=()=>{ const t=el('hpVp'); if(t) t.scrollIntoView({behavior:reduce?'auto':'smooth',block:'center'}); };
const NUM=(lab,v,tol)=>({lab,v,tol});
const TASKS=[
 {k:'wx',q:t2('Poor weather and a late runway change overload the approach. Without changing the weather or the runway change, make the flight fit within your capacity. Then press Check.','Dårlig vær og en sen rullebaneendring overbelaster innflygingen. Uten å endre været eller rullebaneendringen, få flygingen til å passe innenfor kapasiteten. Trykk så Sjekk.'),
  live:()=>{ if(S.mode!=='wl') return [0,t2('Open "Workload and attention".','Åpne «Arbeidsbelastning og oppmerksomhet».')]; if(S.wx!=='poor'||!S.change) return [0,t2('Keep the poor weather and the late runway change on.','Behold dårlig vær og sen rullebaneendring.')];
    const R=WL(); if(R.over>0) return [0,t2('Still overloaded. Which work could you move to a quieter phase, and what makes the task heavier?','Fortsatt overbelastet. Hvilket arbeid kan du flytte til en roligere fase, og hva gjør oppgaven tyngre?')];
    return [1,t2('Yes: brief early, keep the autopilot in, and be rested. On the line you can also reduce the task itself: ask ATC for time or a longer final.','Ja: brief tidlig, behold autopiloten, og vær uthvilt. I praksis kan du også redusere selve oppgaven: be ATC om tid eller en lengre finale.')]; },pre:{mode:'wl',...WL0,wx:'poor',change:true,hand:true}},
 {k:'startle',q:t2('A loud bang and a warning on short final. What is true in the first seconds?','Et kraftig smell og en varsling på kort finale. Hva stemmer i de første sekundene?'),
  opts:[t2('Thinking slows and attention narrows; fly the aircraft first, then diagnose','Tenkningen går tregere og oppmerksomheten snevres inn; fly flyet først, så finn feilen'),t2('Adrenaline makes you think faster; diagnose at once','Adrenalinet gjør at du tenker raskere; finn feilen med en gang'),t2('Startle only affects inexperienced pilots','Skvettreaksjon rammer bare uerfarne piloter'),t2('Read the checklist before touching the controls','Les sjekklisten før du rører kontrollene')],c:0,pre:{mode:'wl',...WL0,startle:true},
  e:t2('Startle and surprise can cost several seconds or more of clear thinking, even for experienced pilots. Aviate first: attitude, power, flight path. Then navigate, communicate, and only then diagnose.','Skvettreaksjon og overraskelse kan koste flere sekunder eller mer av klar tenkning, også for erfarne piloter. Fly først: attityde, kraft, flybane. Så naviger, kommuniser, og først da finn feilen.')},
 {k:'under',q:t2('Three hours into a quiet cruise at night. Where are you on the arousal curve, and what is the risk?','Tre timer inn i en rolig marsj om natten. Hvor er du på aktiveringskurven, og hva er risikoen?'),
  opts:[t2('Low arousal: vigilance and monitoring suffer','Lav aktivering: årvåkenhet og overvåking svikter'),t2('Ideal: nothing is happening, so nothing can go wrong','Ideell: ingenting skjer, så ingenting kan gå galt'),t2('High arousal: overload','Høy aktivering: overbelastning'),t2('It depends only on the autopilot','Det avhenger bare av autopiloten')],c:0,pre:{mode:'wl',...WL0},
  e:t2('Underload is a risk too: you miss a slow change (fuel imbalance, a drifting autopilot mode). Keep a monitoring routine, use the quiet time to plan, and stay active.','Underbelastning er også en risiko: du overser en langsom endring (skjev drivstoffbalanse, en autopilotmodus som glir). Hold en overvåkingsrutine, bruk den rolige tiden til å planlegge, og hold deg aktiv.')},
 {k:'night',q:t2('You report at 22:00 for a 10-hour night duty. Change your sleep plan (not the duty) so the lowest point on duty is out of the high-risk zone. Then press Check.','Du møter kl. 22:00 til en nattjeneste på 10 timer. Endre søvnplanen (ikke tjenesten) så det laveste punktet i tjenesten er utenfor høyrisikosonen. Trykk så Sjekk.'),
  live:()=>{ if(S.mode!=='fat') return [0,t2('Open "Fatigue and the body clock".','Åpne «Tretthet og døgnrytme».')]; if(S.report!==22||S.len!==10) return [0,t2('Keep the duty at 22:00 for 10 h.','Behold tjenesten kl. 22:00 i 10 t.')];
    const D=DAY(), z=H.zone(D.minA); if(z==='high') return [0,t2(`Still high risk: ${nf(D.awakeEnd,0)} h awake at the end. When could you sleep so you start the duty fresh?`,`Fortsatt høy risiko: ${nf(D.awakeEnd,0)} t våken ved slutt. Når kan du sove så du starter tjenesten uthvilt?`)];
    return [1,t2('Yes: sleep in the afternoon or evening before a night duty cuts the hours awake. The body clock still makes 03–06 the hardest part: plan the critical tasks and keep an eye on each other.','Ja: søvn på ettermiddagen eller kvelden før en nattjeneste kutter timene våken. Døgnrytmen gjør fortsatt 03–06 til den tyngste delen: planlegg de kritiske oppgavene og pass på hverandre.')]; },pre:{mode:'fat',bed:23,sleep:8,debt:0,report:22,len:10}},
 {k:'bac',q:t2('About 17 hours awake impairs performance roughly like a blood alcohol of… (in ‰)','Rundt 17 timer våken svekker prestasjonen omtrent som en promille på … (i ‰)'),
  ins:[NUM(t2('Blood alcohol (‰)','Promille (‰)'),0.5,0.11)],pre:{mode:'fat',bed:23,sleep:8,debt:0,report:14,len:8},
  e:t2('About 0.5 ‰ (0.05 %), and about 1 ‰ after 24 hours, in a well-known study. That is far above the 0.2 ‰ limit for crew.','Rundt 0,5 ‰ (0,05 %), og rundt 1 ‰ etter 24 timer, i en kjent studie. Det er langt over grensen på 0,2 ‰ for besetning.')},
 {k:'wocl',q:t2('When is the window of circadian low (WOCL) in the EASA flight time rules?','Når er døgnrytmens bunn (WOCL) i EASAs flytidsregler?'),
  opts:[t2('02:00–05:59 in the time zone you are acclimatised to','02:00–05:59 i tidssonen du er akklimatisert til'),t2('13:00–15:00 local time','13:00–15:00 lokal tid'),t2('22:00–02:00 UTC','22:00–02:00 UTC'),t2('Any time after 16 hours awake','Når som helst etter 16 timer våken')],c:0,pre:{mode:'fat',bed:23,sleep:8,debt:0,report:22,len:10},
  e:t2('The body clock is at its lowest in the early morning. There is a smaller dip in the early afternoon too.','Døgnrytmen er på sitt laveste tidlig om morgenen. Det er også en mindre dupp tidlig på ettermiddagen.')},
 {k:'tem1',q:t2('Late runway change: switch on ONE countermeasure that stops the chain as early as possible. Then press Check.','Sen rullebaneendring: slå på ETT mottiltak som stopper kjeden så tidlig som mulig. Trykk så Sjekk.'),
  live:()=>{ if(S.mode!=='tem'||S.sc!=='rwy') return [0,t2('Open "Threat and error" and pick "Late runway change".','Åpne «Trussel og feil» og velg «Sen rullebaneendring».')]; const n=Object.values(S.cm).filter(Boolean).length; if(n!==1) return [0,t2('Exactly one countermeasure, please.','Nøyaktig ett mottiltak, takk.')];
    const T=temState(); if(T.stage>0) return [0,t2(`That works, but only at the ${L(STG[T.stage]).toLowerCase()}. Which one deals with the threat itself?`,`Det virker, men først ved ${L(STG[T.stage]).toLowerCase()}. Hvilket håndterer selve trusselen?`)];
    return [1,t2('Yes: plan and brief. Asking for time and briefing the new approach manages the threat before any error is made.','Ja: planlegg og brief. Å be om tid og brife den nye innflygingen håndterer trusselen før noen feil gjøres.')]; },pre:{mode:'tem',sc:'rwy',cm:{...CM0}}},
 {k:'tem2',q:t2('In threat and error management, "ATC gives a late runway change" is…','I trussel- og feilhåndtering er «ATC gir en sen rullebaneendring» …'),
  opts:[t2('a threat','en trussel'),t2('an error','en feil'),t2('an undesired aircraft state','en uønsket flytilstand'),t2('a violation','et brudd')],c:0,pre:{mode:'tem',sc:'rwy',cm:{...CM0}},
  e:t2('Threats come from outside the crew (weather, ATC, terrain, other traffic, aircraft faults) and must be managed. Errors are the crew\'s own actions or inactions.','Trusler kommer utenfra besetningen (vær, ATC, terreng, annen trafikk, feil på flyet) og må håndteres. Feil er besetningens egne handlinger eller unnlatelser.')},
 {k:'tuc',dp:1,q:t2('Rapid decompression at FL350. Typically, how long do you have before you can no longer act usefully (time of useful consciousness)?','Rask dekompresjon i FL350. Typisk, hvor lang tid har du før du ikke lenger kan handle fornuftig (time of useful consciousness)?'),
  opts:[t2('About 30–60 s, less after a rapid decompression','Rundt 30–60 s, mindre etter en rask dekompresjon'),t2('About 5 minutes','Rundt 5 minutter'),t2('About 20 minutes','Rundt 20 minutter'),t2('Several hours','Flere timer')],c:0,pre:{mode:'fat',bed:23,sleep:8,debt:0,report:8,len:10},
  e:t2('Typical values: FL250 3–5 min, FL300 1–2 min, FL350 30–60 s, FL400 15–20 s, roughly halved by a rapid decompression or activity. Oxygen mask on first, at once. More in the pressurisation lab.','Typiske verdier: FL250 3–5 min, FL300 1–2 min, FL350 30–60 s, FL400 15–20 s, omtrent halvert ved rask dekompresjon eller aktivitet. Oksygenmasken på først, med en gang. Mer i trykkabinlabben.')}];
const tasks=()=>TASKS.filter(t=>!t.dp||deepOn());
function drawTask(){ const TS=tasks(); ti=clamp(ti,0,TS.length-1); const t=TS[ti], n=TS.length, a=ansv[t.k];
  let h=`<div class="th"><span class="n">${L(t2('Task','Oppgave'))} ${ti+1} ${L(t2('of','av'))} ${n}</span><span class="dots">${TS.map((x,i)=>`<button type="button" data-i="${i}" class="${i===ti?'on':''}" aria-label="${L(t2('Task','Oppgave'))} ${i+1}"></button>`).join('')}</span></div><p class="q">${L(t.q)}</p>`;
  if(t.ins){ h+=`<div class="ins">${t.ins.map((x,j)=>{ const v=a&&a[j]; const ok=v!=null&&v!==''&&Math.abs(parseFloat(String(v).replace(',','.').replace(/\s/g,''))-x.v)<=x.tol; return `<label>${L(x.lab)}<input type="text" inputmode="decimal" data-j="${j}" value="${v??''}" class="${done[t.k]?(ok?'right':'wrong'):''}" autocomplete="off"></label>`; }).join('')}<button type="button" class="btn pri sm" data-chk="1">${L(t2('Check','Sjekk'))}</button></div>`;
    h+=`<span class="fb${done[t.k]===1?' ok':''}">${done[t.k]?'<b>'+L(done[t.k]===1?t2('Right.','Riktig.'):t2('Not quite.','Ikke helt.'))+'</b> '+L(t.e):''}</span>`; }
  else if(t.opts){ h+=`<div class="opts">${t.opts.map((o,j)=>`<button type="button" data-o="${j}" class="${a!=null&&j===t.c?'right':''}${a===j&&j!==t.c?' wrong':''}">${L(o)}</button>`).join('')}</div><span class="fb${a===t.c?' ok':''}">${a!=null?'<b>'+L(a===t.c?t2('Right.','Riktig.'):t2('Not quite.','Ikke helt.'))+'</b> '+L(t.e):''}</span>`; }
  else { h+=`<div class="ins"><button type="button" class="btn pri sm" data-chk="1">${L(t2('Check','Sjekk'))}</button></div><span class="fb${done[t.k]&&done[t.k][0]?' ok':''}">${done[t.k]?(done[t.k][0]?'<b>✓</b> ':'')+L(done[t.k][1]):''}</span>`; }
  h+=`<div class="nav"><button type="button" class="btn sm" data-go="1">${L(t.live?t2('Set it up in the model','Sett det opp i modellen'):t2('Check it in the model','Sjekk i modellen'))} ↑</button><span class="sp"></span><button type="button" class="btn sm" data-p="1" ${ti===0?'disabled':''}>← ${L(t2('Previous','Forrige'))}</button><button type="button" class="btn sm" data-n="1" ${ti===n-1?'disabled':''}>${L(t2('Next','Neste'))} →</button></div>`;
  el('tstep').innerHTML=h; }
el('tstep').addEventListener('input',e=>{ const i=e.target.closest('input'); if(!i) return; const t=tasks()[ti]; (ansv[t.k]=ansv[t.k]||[])[+i.dataset.j]=i.value; });
el('tstep').addEventListener('keydown',e=>{ if(e.key==='Enter'&&e.target.closest('input')){ const b=el('tstep').querySelector('[data-chk]'); if(b) b.click(); } });
el('tstep').addEventListener('click',e=>{ const b=e.target.closest('button'); if(!b) return; const TS=tasks(), t=TS[ti];
  if(b.dataset.i!=null){ ti=+b.dataset.i; drawTask(); return; } if(b.dataset.p){ ti--; drawTask(); return; } if(b.dataset.n){ ti++; drawTask(); return; }
  if(b.dataset.go){ setS(t.pre); goModel(); return; }
  if(b.dataset.o!=null){ ansv[t.k]=+b.dataset.o; drawTask(); return; }
  if(b.dataset.chk){ if(t.live){ done[t.k]=t.live(); drawTask(); return; }
    const a=ansv[t.k]||[]; done[t.k]=t.ins.every((x,j)=>a[j]!=null&&a[j]!==''&&Math.abs(parseFloat(String(a[j]).replace(',','.').replace(/\s/g,''))-x.v)<=x.tol)?1:2; drawTask(); } });

/* ---------------- Understand: key concept cards ---------------- */
const {sv,tx,ar}=KCS;
const go=o=>({click:()=>setS(o),to:'#hpVp'});
const KC=[
 Object.assign({k:'att',t:t2('Attention is limited','Oppmerksomheten er begrenset'),d:t2('You can attend to only one demanding thing at a time. "Multitasking" is <b>switching</b>, and each switch costs time and lets things slip.','Du kan bare gi oppmerksomhet til én krevende ting om gangen. «Multitasking» er å <b>bytte</b>, og hvert bytte koster tid og slipper ting gjennom.'),
  dd:t2('Working memory holds only about 5–9 items (7 ± 2) for a short time: write clearances down and read them back.','Arbeidsminnet holder bare rundt 5–9 elementer (7 ± 2) en kort stund: skriv ned klareringer og les dem tilbake.'),
  ill:()=>sv(`<circle cx="40" cy="32" r="16" fill="none" stroke="#f0c470" stroke-width="2"/>${ar(60,32,95,18,'#eef3f7')}${ar(60,32,95,46,'#5e6d7c')}${tx(100,20,'ATC','#eef3f7','start',8)}${tx(100,50,'checklist','#5e6d7c','start',8)}`)},go({mode:'wl',...WL0,wx:'poor',change:true})),
 Object.assign({k:'wl',t:t2('Workload against capacity','Arbeidsbelastning mot kapasitet'),d:t2('Workload peaks at <b>take-off and the approach</b>. When demand exceeds capacity you tunnel, skip items and make errors. <b>Plan and brief in the quiet phases.</b>','Arbeidsbelastningen topper seg ved <b>start og innflyging</b>. Når kravet er større enn kapasiteten, får du tunnelsyn, hopper over punkter og gjør feil. <b>Planlegg og brief i de rolige fasene.</b>'),
  ill:()=>sv(`<path d="M10,54 L40,20 L70,40 L120,52 L150,22 L190,16" fill="none" stroke="#f0c470" stroke-width="2"/><line x1="10" y1="22" x2="190" y2="22" stroke="#71cc93" stroke-dasharray="4 3"/><path d="M178,22 L190,16 L190,22Z" fill="#ec5a47"/>`)},go({mode:'wl',...WL0,wx:'poor',change:true})),
 Object.assign({k:'under',t:t2('Too little is a risk too','For lite er også en risiko'),d:t2('Performance is best at medium arousal (the <b>inverted U</b>). In a long quiet cruise, vigilance drops and slow changes go unnoticed.','Prestasjonen er best ved middels aktivering (den <b>omvendte U-en</b>). I en lang rolig marsj faller årvåkenheten og langsomme endringer blir oversett.'),
  ill:()=>sv(`<path d="M20,56 C60,56 70,10 100,10 C130,10 140,56 180,56" fill="none" stroke="#eef3f7" stroke-width="2"/><circle cx="34" cy="54" r="4" fill="#7fcbe8"/><circle cx="100" cy="10" r="4" fill="#71cc93"/><circle cx="168" cy="54" r="4" fill="#ec5a47"/>`)},go({mode:'wl',...WL0})),
 Object.assign({k:'startle',t:t2('Startle and surprise','Skvettreaksjon og overraskelse'),d:t2('A sudden event can cost <b>seconds of clear thinking</b>, even for experienced pilots. Fly the aircraft first (aviate, navigate, communicate), then diagnose.','En plutselig hendelse kan koste <b>sekunder med klar tenkning</b>, også for erfarne piloter. Fly flyet først (fly, naviger, kommuniser), finn feilen etterpå.'),
  ill:()=>sv(`<path d="M10,46 L120,46 L128,10 L136,46 L190,46" fill="none" stroke="#f0c470" stroke-width="2"/><path d="M10,24 L120,24 L128,52 Q150,30 190,24" fill="none" stroke="#71cc93" stroke-dasharray="4 3"/>`)},go({mode:'wl',...WL0,startle:true})),
 Object.assign({k:'auto',t:t2('Automation: know what it is doing','Automatikk: vit hva den gjør'),d:t2('Automation lowers workload but invites <b>complacency</b> and <b>mode confusion</b>. Read the mode annunciations, ask "what is it doing now?", and if it surprises you, take a lower level of automation. <a href="autoflight.html">Autopilot lab</a>.','Automatikk senker arbeidsbelastningen, men inviterer til <b>selvtilfredshet</b> og <b>modusforvirring</b>. Les modusvisningene, spør «hva gjør den nå?», og overrasker den deg, gå ned et automatikknivå. <a href="autoflight.html">Autopilotlabben</a>.'),
  ill:()=>sv(`<rect x="20" y="16" width="160" height="22" rx="3" fill="#0c1217" stroke="#6f7e8b"/>${tx(50,31,'SPEED','#71cc93','middle',8)}${tx(100,31,'ALT*','#7fcbe8','middle',8)}${tx(150,31,'NAV','#71cc93','middle',8)}${tx(100,54,'what is it doing now?','#f0c470','middle',8)}`)},go({mode:'wl',...WL0,hand:true,wx:'poor'})),
 Object.assign({k:'tem',t:t2('Threat and error management','Trussel- og feilhåndtering'),d:t2('<b>Threats</b> come from outside the crew, <b>errors</b> from the crew, and unmanaged they lead to an <b>undesired aircraft state</b>. Anticipate, trap, recover: the earlier the better.','<b>Trusler</b> kommer utenfra besetningen, <b>feil</b> fra besetningen, og uhåndtert fører de til en <b>uønsket flytilstand</b>. Forutse, fang, gjenopprett: jo tidligere jo bedre.'),
  ill:()=>sv(`${['T','E','UAS','!'].map((s,i)=>`<rect x="${8+i*48}" y="20" width="38" height="24" rx="4" fill="#0c1217" stroke="${i===3?'#ec5a47':'#f0c470'}"/>${tx(27+i*48,36,s,i===3?'#ec5a47':'#f0c470','middle',9)}`).join('')}`)},go({mode:'tem',sc:'rwy',cm:{...CM0}})),
 Object.assign({k:'crm',t:t2('CRM: brief, crosscheck, speak up','CRM: brief, kryssjekk, si fra'),d:t2('Good crews <b>brief</b> what they expect, <b>follow SOPs</b>, <b>crosscheck</b> each other and <b>speak up</b> clearly when something is wrong, whatever the rank.','Gode besetninger <b>brifer</b> det de forventer, <b>følger SOP-er</b>, <b>kryssjekker</b> hverandre og <b>sier tydelig fra</b> når noe er galt, uansett grad.'),
  dd:t2('Use closed-loop communication (say, read back, confirm). Speaking up works best in steps: get attention, state the concern, propose an action, get agreement, and in the end act, e.g. "Go around."','Bruk lukket sløyfe (si, les tilbake, bekreft). Å si fra virker best i trinn: få oppmerksomhet, si bekymringen, foreslå et tiltak, få enighet, og til slutt handle, for eksempel «Go around».'),
  ill:()=>sv(`<circle cx="50" cy="28" r="10" fill="none" stroke="#eef3f7"/><circle cx="150" cy="28" r="10" fill="none" stroke="#eef3f7"/>${ar(64,22,136,22,'#71cc93')}${ar(136,36,64,36,'#7fcbe8')}${tx(100,56,'read back · confirm','#8b99a7','middle',8)}`)},go({mode:'tem',sc:'rwy',cm:{...CM0,speak:true}})),
 Object.assign({k:'dec',t:t2('Decide with a model','Bestem med en modell'),d:t2('<b>Under pressure, use a structure</b>, for example <b>FOR-DEC</b> or <b>DODAR</b>, two models in wide use. FOR-DEC: Facts, Options, Risks and benefits, Decision, Execution, Check. DODAR: Diagnose, Options, Decide, Assign, Review.','<b>Under press, bruk en struktur</b>, for eksempel <b>FOR-DEC</b> eller <b>DODAR</b>, to modeller i utstrakt bruk. FOR-DEC: Fakta, Alternativer, Risiko og nytte, Beslutning, Utførelse, Kontroll. DODAR: Diagnose, Alternativer, Bestem, Fordel oppgaver, Gjennomgå.'),
  dd:t2('Beware of plan continuation bias ("get-there-itis"): the closer you are to the goal, the harder it is to change the plan. Set decision points in advance.','Vokt deg for plan continuation bias («hjem-feber»): jo nærmere målet, jo vanskeligere er det å endre planen. Sett beslutningspunkter på forhånd.'),
  ill:()=>sv(`${['F','O','R','D','E','C'].map((s,i)=>`<rect x="${10+i*31}" y="20" width="26" height="24" rx="4" fill="#0c1217" stroke="#7fcbe8"/>${tx(23+i*31,36,s,'#7fcbe8','middle',10)}`).join('')}`)},go({mode:'tem',sc:'wx',cm:{...CM0,brief:true}})),
 Object.assign({k:'fat',t:t2('Fatigue: sleep and the body clock','Tretthet: søvn og døgnrytme'),d:t2('Alertness falls with <b>hours awake</b> and with the <b>body clock</b>, lowest around 02–06. Sleep debt adds up. 17 h awake is roughly like 0.5 ‰ blood alcohol (typical).','Årvåkenheten faller med <b>timer våken</b> og med <b>døgnrytmen</b>, lavest rundt 02–06. Søvnunderskudd hoper seg opp. 17 t våken er omtrent som 0,5 ‰ promille (typisk).'),
  dd:t2('Fatigue risk management: plan rest, sleep before night duties, report fatigue without blame, and do not fly if you are not fit. A short nap (about 20–30 min) helps without much grogginess.','Håndtering av tretthetsrisiko: planlegg hvile, sov før nattjenester, meld tretthet uten skyld, og ikke fly hvis du ikke er skikket. En kort lur (rundt 20–30 min) hjelper uten mye døsighet etterpå.'),
  ill:()=>sv(`<path d="M10,20 C50,14 80,30 110,50 C130,58 150,40 190,24" fill="none" stroke="#eef3f7" stroke-width="2"/><rect x="104" y="6" width="34" height="54" fill="rgba(127,203,232,.15)"/>${tx(121,16,'02–06','#7fcbe8','middle',8)}`)},go({mode:'fat',bed:23,sleep:8,debt:0,report:22,len:10})),
 {k:'alc',t:t2('Alcohol and medicines','Alkohol og medisiner'),d:t2('Crew limit in the EU: <b>0.2 ‰</b> (0.2 g/L blood). Many operators require no alcohol for at least 8–12 h before duty (typical); a hangover still impairs. Many over-the-counter medicines (antihistamines, sleeping aids, codeine) are not compatible with flying: ask an aeromedical examiner.','Grense for besetning i EU: <b>0,2 ‰</b> (0,2 g/L blod). Mange operatører krever ingen alkohol minst 8–12 t før tjeneste (typisk); bakrus svekker fortsatt. Mange reseptfrie medisiner (antihistaminer, sovemidler, kodein) passer ikke med flyging: spør en flylege.'),
  ill:()=>sv(`<path d="M40,10 L60,10 L56,40 Q50,48 44,40Z" fill="none" stroke="#eef3f7"/><line x1="50" y1="44" x2="50" y2="56" stroke="#eef3f7"/>${tx(120,30,'0.2 ‰','#f0c470','middle',12)}${tx(120,48,'limit','#8b99a7','middle',8)}`)},
 {k:'hyp',t:t2('Hypoxia is insidious','Hypoksi sniker seg inn'),d:t2('Lack of oxygen <b>impairs judgement before you notice it</b>, often with a feeling of well-being. Time of useful consciousness shrinks fast with altitude: typically 3–5 min at FL250, 30–60 s at FL350. Mask on first. <a href="pressurisation.html">Pressurisation lab</a>.','Mangel på oksygen <b>svekker vurderingsevnen før du merker det</b>, ofte med en følelse av velvære. Tiden med nyttig bevissthet krymper fort med høyden: typisk 3–5 min i FL250, 30–60 s i FL350. Masken på først. <a href="pressurisation.html">Trykkabinlabben</a>.'),
  ill:()=>sv(`<path d="M20,10 C40,40 80,52 180,56" fill="none" stroke="#ec5a47" stroke-width="2"/>${tx(30,12,'FL180 20–30 min','#8b99a7','start',7.5)}${tx(110,40,'FL350 30–60 s','#f0c470','start',7.5)}`)}];
KCS.render(el('kcGrid'),KC);

/* ---------------- deep-dive folds ---------------- */
const P=s=>`<p>${s}</p>`;
const tab=rows=>`<div class="wrapx"><table class="ftab">${rows.map((r,j)=>`<tr>${r.map(c=>j?`<td>${L(c)}</td>`:`<th>${L(c)}</th>`).join('')}</tr>`).join('')}</table></div>`;
const TUC=[[t2('Altitude','Høyde'),t2('Time of useful consciousness (typical, at rest)','Tid med nyttig bevissthet (typisk, i ro)')],[t2('FL180','FL180'),t2('20–30 min','20–30 min')],[t2('FL220','FL220'),t2('5–10 min','5–10 min')],[t2('FL250','FL250'),t2('3–5 min','3–5 min')],[t2('FL300','FL300'),t2('1–2 min','1–2 min')],[t2('FL350','FL350'),t2('30–60 s','30–60 s')],[t2('FL400','FL400'),t2('15–20 s','15–20 s')]];
const DM=[[t2('FOR-DEC','FOR-DEC'),t2('DODAR','DODAR')],[t2('<b>F</b>acts: what is the situation?','<b>F</b>akta: hva er situasjonen?'),t2('<b>D</b>iagnose: what is the problem?','<b>D</b>iagnose: hva er problemet?')],[t2('<b>O</b>ptions: what can we do?','<b>O</b>ptions (alternativer): hva kan vi gjøre?'),t2('<b>O</b>ptions: what can we do?','<b>O</b>ptions (alternativer): hva kan vi gjøre?')],[t2('<b>R</b>isks and benefits of each','<b>R</b>isiko og nytte for hvert'),t2('<b>D</b>ecide','<b>D</b>ecide (bestem)')],[t2('<b>D</b>ecision','<b>D</b>ecision (beslutning)'),t2('<b>A</b>ssign tasks','<b>A</b>ssign (fordel oppgaver)')],[t2('<b>E</b>xecution: who does what','<b>E</b>xecution (utførelse): hvem gjør hva'),t2('<b>R</b>eview: is it working?','<b>R</b>eview (gjennomgå): virker det?')],[t2('<b>C</b>heck: is it working?','<b>C</b>heck (kontroll): virker det?'),t2('','')]];
const DD=[
 ['info',t2('Information processing and situational awareness','Informasjonsbehandling og situasjonsforståelse'),t2('perception, memory, mental models','persepsjon, hukommelse, mentale modeller'),[
  t2(P('Information flows from the senses through <b>perception</b> (making sense of it, shaped by what you expect) into <b>working memory</b>, which holds about 5–9 items for a short time unless rehearsed, and is easily disrupted. <b>Long-term memory</b> holds knowledge and skills; well-practised skills run almost automatically and free attention, but also cause slips when the situation is slightly different.')+P('<b>Situational awareness</b> has three levels: perceive what is happening, understand what it means, and project what will happen next. It is lost through overload, distraction, fixation and <b>expectation</b>: you see what you expect (a familiar clearance, the usual runway), and you look for evidence that confirms your picture rather than evidence against it (confirmation bias).'),
     P('Informasjon går fra sansene gjennom <b>persepsjon</b> (å gi det mening, preget av hva du forventer) inn i <b>arbeidsminnet</b>, som holder rundt 5–9 elementer en kort stund hvis du ikke repeterer, og som lett forstyrres. <b>Langtidsminnet</b> holder kunnskap og ferdigheter; godt innøvde ferdigheter går nesten automatisk og frigjør oppmerksomhet, men gir også glipp når situasjonen er litt annerledes.')+P('<b>Situasjonsforståelse</b> har tre nivåer: oppfatte hva som skjer, forstå hva det betyr, og forutse hva som skjer videre. Den tapes ved overbelastning, distraksjon, fiksering og <b>forventning</b>: du ser det du forventer (en kjent klarering, den vanlige rullebanen), og du leter etter det som bekrefter bildet ditt i stedet for det som motsier det (bekreftelsesfelle).'))]],
 ['stress',t2('Stress, startle and workload','Stress, skvettreaksjon og arbeidsbelastning'),t2('what helps','det som hjelper'),[
  t2(P('Some arousal helps; too much narrows attention (tunnelling), drops the less important items first, and pushes you back to old habits. Stress builds from the task, the environment (noise, heat, turbulence) and life outside the cockpit. Long-term stress and life events reduce capacity before the flight even starts.')+P('<b>Startle</b> is the reflex to a sudden event; <b>surprise</b> is the mental shock when things do not match what you expected. Together they can disrupt clear thinking for several seconds or more. What helps: fly the aircraft first; a deliberate pause and a breath before acting on a non-urgent problem; training with unexpected events; and briefing "what if" before critical phases.')+P('<b>Managing workload:</b> plan ahead, brief early, prioritise (aviate, navigate, communicate), delegate in a crew, use the automation at the right level, and when it is all too much, reduce the task: a hold, a vector, a longer final, a go-around.'),
     P('Litt aktivering hjelper; for mye snevrer inn oppmerksomheten (tunnelsyn), dropper de minst viktige tingene først og skyver deg tilbake til gamle vaner. Stress bygges av oppgaven, omgivelsene (støy, varme, turbulens) og livet utenfor cockpit. Langvarig stress og livshendelser senker kapasiteten før flygingen i det hele tatt har startet.')+P('<b>Skvettreaksjon</b> er refleksen på en plutselig hendelse; <b>overraskelse</b> er det mentale sjokket når ting ikke stemmer med det du forventet. Sammen kan de forstyrre klar tenkning i flere sekunder eller mer. Det som hjelper: fly flyet først; en bevisst pause og et pust før du handler på et problem som ikke haster; trening med uventede hendelser; og å brife «hva om» før kritiske faser.')+P('<b>Styre arbeidsbelastningen:</b> planlegg, brief tidlig, prioriter (fly, naviger, kommuniser), deleger i en besetning, bruk automatikken på riktig nivå, og når det blir for mye, reduser oppgaven: en holding, en vektor, en lengre finale, en go-around.'))]],
 ['auto',t2('Automation','Automatikk'),t2('complacency, mode confusion, skill fade','selvtilfredshet, modusforvirring, ferdighetstap'),[
  t2(P('Automation lowers workload in the routine and can raise it when things go wrong. Typical traps: <b>complacency</b> (trusting it and stopping monitoring), <b>mode confusion</b> (the system does what it was set to do, not what you think), surprises at mode changes, and <b>manual skill fade</b>.')+P('Good practice: read the flight mode annunciations out loud on every change, verify every FMS entry with the other pilot, ask "what is it doing now, what will it do next?", and if the aircraft does not do what you expect, take a lower level of automation and fly. Keep hand-flying skills current when the conditions and the rules allow. See the <a href="autoflight.html">automation and warnings lab</a>.'),
     P('Automatikk senker arbeidsbelastningen i rutinen og kan øke den når noe går galt. Typiske feller: <b>selvtilfredshet</b> (stoler på den og slutter å overvåke), <b>modusforvirring</b> (systemet gjør det det ble satt til, ikke det du tror), overraskelser ved modusbytter, og <b>tap av manuelle ferdigheter</b>.')+P('God praksis: les modusvisningene høyt ved hver endring, verifiser hver FMS-innlegging med den andre piloten, spør «hva gjør den nå, hva gjør den så?», og gjør ikke flyet det du forventer, gå ned et automatikknivå og fly. Hold håndflygingen ved like når forholdene og reglene tillater det. Se <a href="autoflight.html">labben om automatikk og varsling</a>.'))]],
 ['crm',t2('Errors, TEM and CRM','Feil, TEM og CRM'),t2('slips, lapses, mistakes, and the defences','glipp, forglemmelser, feiltakelser, og forsvarene'),[
  t2(P('<b>Error types:</b> a <b>slip</b> is the right plan done wrong (selecting the wrong switch), a <b>lapse</b> is something forgotten (a checklist item skipped after an interruption), a <b>mistake</b> is the wrong plan (misjudging the weather). A <b>violation</b> is a deliberate deviation from a rule. Errors are normal and cannot be eliminated; the aim is to catch them.')+P('<b>The Swiss-cheese model:</b> an accident needs holes in several layers of defence to line up: the organisation, supervision, preconditions (fatigue, poor procedures) and the crew\'s own actions. Most layers have latent holes, so every layer counts.')+P('<b>Threat and error management</b> gives the crew three jobs: anticipate threats (brief them), recognise and trap errors (monitor, crosscheck, SOPs), and recover from undesired aircraft states (fly the aircraft first, then fix the cause).')+P('<b>CRM</b> is the use of all resources (people, information, equipment) for a safe flight: communication with closed loops, briefings that say what to expect and what to do if it does not happen, assertiveness that rises step by step to a clear action, leadership that invites input, and a flat enough authority gradient for the junior pilot to speak up.'),
     P('<b>Feiltyper:</b> en <b>glipp</b> er riktig plan utført feil (feil bryter), en <b>forglemmelse</b> er noe som glemmes (et sjekklistepunkt hoppet over etter et avbrudd), en <b>feiltakelse</b> er feil plan (feilvurdert vær). Et <b>brudd</b> er et bevisst avvik fra en regel. Feil er normalt og kan ikke fjernes; målet er å fange dem.')+P('<b>Sveitserostmodellen:</b> en ulykke krever at hull i flere forsvarslag står på linje: organisasjonen, tilsyn, forutsetninger (tretthet, dårlige prosedyrer) og besetningens egne handlinger. De fleste lag har skjulte hull, så hvert lag teller.')+P('<b>Trussel- og feilhåndtering</b> gir besetningen tre jobber: forutse trusler (brief dem), oppdage og fange feil (overvåk, kryssjekk, SOP-er), og gjenopprette fra uønskede flytilstander (fly flyet først, rett årsaken etterpå).')+P('<b>CRM</b> er bruk av alle ressurser (folk, informasjon, utstyr) for en trygg flyging: kommunikasjon i lukket sløyfe, briefer som sier hva vi forventer og hva vi gjør hvis det ikke skjer, selvhevdelse som øker trinnvis mot en klar handling, ledelse som inviterer innspill, og en flat nok autoritetsgradient til at den yngste piloten sier fra.'))]],
 ['dec',t2('Decision making','Beslutninger'),t2('two models and the biases','to modeller og fellene'),['DM',
  t2(P('These are examples; operators use different models and the steps are what matters: gather the facts, look at more than one option, weigh the risks, decide, act, and check the result. Time is part of it: with an urgent problem, fly first and keep the decision short.')+P('<b>Biases to know:</b> plan continuation (pressing on as the situation gets worse), confirmation (looking only for evidence that fits), anchoring on the first idea, and the pressure of time, schedule and passengers. <b>Hazardous attitudes</b> in the classic list: anti-authority, impulsivity, invulnerability, macho, resignation.'),
     P('Dette er eksempler; operatører bruker ulike modeller, og det er trinnene som teller: samle fakta, se på mer enn ett alternativ, vei risikoene, bestem, handle, og kontroller resultatet. Tid er en del av det: med et presserende problem, fly først og hold beslutningen kort.')+P('<b>Feller å kjenne:</b> plan continuation (å fortsette mens situasjonen blir verre), bekreftelse (å bare se etter det som passer), forankring i den første ideen, og presset fra tid, rutetider og passasjerer. <b>Farlige holdninger</b> i den klassiske lista: anti-autoritet, impulsivitet, usårbarhet, macho, resignasjon.'))]],
 ['fat',t2('Fatigue and fatigue risk management','Tretthet og håndtering av tretthetsrisiko'),t2('sleep, the body clock, the rules','søvn, døgnrytme, reglene'),[
  t2(P('Adults typically need 7–9 h of sleep. Missed sleep adds up as <b>sleep debt</b>, which only sleep repays. The body clock (circadian rhythm) makes alertness lowest around 02–06 and dips a little in the early afternoon. Crossing time zones shifts the clock; it typically adjusts by about one time zone per day, faster flying west than east.')+P('Fatigue lowers attention, slows reactions, worsens memory and judgement, and brings <b>microsleeps</b> you do not notice. You are a poor judge of your own fatigue.')+P('<b>The rules:</b> EASA flight time limitations set duty, flight time and rest limits and define the window of circadian low (WOCL) as 02:00–05:59 in the time zone you are acclimatised to. Operators may use a <b>fatigue risk management</b> system built on data and reports. Your part: use rest to sleep, plan sleep before night and early duties, report fatigue, and do not fly if you are unfit. Caffeine helps for a while; a short nap (about 20–30 min) helps without much sleep inertia.'),
     P('Voksne trenger typisk 7–9 t søvn. Tapt søvn hoper seg opp som <b>søvnunderskudd</b>, som bare søvn betaler tilbake. Døgnrytmen gjør årvåkenheten lavest rundt 02–06 og gir en liten dupp tidlig på ettermiddagen. Å krysse tidssoner flytter klokka; den justeres typisk med rundt én tidssone per døgn, raskere vestover enn østover.')+P('Tretthet senker oppmerksomheten, gir tregere reaksjoner, dårligere hukommelse og vurderingsevne, og <b>mikrosøvn</b> du ikke merker. Du er en dårlig dommer over din egen tretthet.')+P('<b>Reglene:</b> EASAs flytidsbegrensninger setter grenser for tjeneste, flytid og hvile og definerer døgnrytmens bunn (WOCL) som 02:00–05:59 i tidssonen du er akklimatisert til. Operatører kan bruke et system for <b>håndtering av tretthetsrisiko</b> bygget på data og rapporter. Din del: bruk hvilen til å sove, planlegg søvn før natt- og tidligtjenester, meld tretthet, og ikke fly hvis du ikke er skikket. Koffein hjelper en stund; en kort lur (rundt 20–30 min) hjelper uten mye søvninerti.'))]],
 ['med',t2('Alcohol, medicines and fitness','Alkohol, medisiner og skikkethet'),t2('the limits and the rule of thumb','grensene og tommelfingerregelen'),[
  t2(P('<b>Alcohol:</b> the EU limit for flight and cabin crew is 0.2 g/L in the blood (0.2 ‰), and crews can be tested. The body removes roughly 0.1–0.2 ‰ per hour (typical), and nothing speeds it up. Many operators set "no alcohol within 8–12 h of duty" (typical; follow your operator), but after heavy drinking you can be over the limit much longer, and a hangover impairs even at zero.')+P('<b>Medicines:</b> many common medicines cause drowsiness or affect vision and balance: antihistamines, sleeping aids, strong painkillers (codeine), anti-motion-sickness tablets. Do not fly on a new medicine until you know how it affects you, and ask an aeromedical examiner. <b>Fitness:</b> you must not fly if you know or suspect your medical fitness is reduced (illness, injury, surgery, pregnancy, blood donation, diving: typically 24 h after scuba diving).'),
     P('<b>Alkohol:</b> grensen i EU for flygere og kabinbesetning er 0,2 g/L i blodet (0,2 ‰), og besetninger kan testes. Kroppen fjerner rundt 0,1–0,2 ‰ i timen (typisk), og ingenting øker farten. Mange operatører har «ingen alkohol 8–12 t før tjeneste» (typisk; følg din operatør), men etter mye drikking kan du være over grensen mye lenger, og bakrus svekker selv på null.')+P('<b>Medisiner:</b> mange vanlige medisiner gir døsighet eller påvirker syn og balanse: antihistaminer, sovemidler, sterke smertestillende (kodein), tabletter mot reisesyke. Ikke fly på en ny medisin før du vet hvordan den virker på deg, og spør en flylege. <b>Skikkethet:</b> du skal ikke fly hvis du vet eller mistenker at helsen din er svekket (sykdom, skade, operasjon, graviditet, blodgivning, dykking: typisk 24 t etter dykking med flasker).'))]],
 ['hyp',t2('Hypoxia and hyperventilation','Hypoksi og hyperventilering'),t2('time of useful consciousness','tid med nyttig bevissthet'),['TUC',
  t2(P('Hypoxia is dangerous because the first thing to go is your judgement. Typical signs: euphoria or a sense of well-being, poor concentration, slow thinking, headache, tunnel and blurred vision, blue lips and nail beds (cyanosis), tingling. Night vision suffers first, from fairly low altitudes. The times above are typical and shrink with activity, smoking, fatigue and a rapid decompression (roughly halved).')+P('<b>Hyperventilation</b> (breathing too much under stress) gives similar signs: dizziness, tingling, feeling cold. Fix it by breathing slowly and talking; if you are not sure which it is at altitude, treat it as hypoxia: oxygen first. The <a href="pressurisation.html">pressurisation lab</a> shows cabin altitude, decompression and the oxygen rules.'),
     P('Hypoksi er farlig fordi det første som forsvinner er vurderingsevnen. Typiske tegn: eufori eller velvære, dårlig konsentrasjon, treg tenkning, hodepine, tunnelsyn og tåkesyn, blå lepper og negler (cyanose), prikking. Nattsynet svekkes først, fra ganske lave høyder. Tidene over er typiske og krymper med aktivitet, røyking, tretthet og en rask dekompresjon (omtrent halvert).')+P('<b>Hyperventilering</b> (å puste for mye under stress) gir lignende tegn: svimmelhet, prikking, kuldefølelse. Rett det ved å puste sakte og snakke; er du usikker på hva det er i høyden, behandle det som hypoksi: oksygen først. <a href="pressurisation.html">Trykkabinlabben</a> viser kabinhøyde, dekompresjon og oksygenreglene.'))]],
 ['vis',t2('Vision and see-and-avoid','Syn og se-og-unngå'),t2('scanning, night vision','scanning, nattsyn'),[
  t2(P('A traffic conflict on a collision course <b>does not move</b> on the windscreen; it just grows, slowly at first and very fast at the end. The eye sees detail only in a small central area, so <b>scan</b> in sectors of about 10°, pausing about a second on each (typical). With nothing to focus on (haze, blue sky), the eyes relax to a short focus (empty-field myopia): focus on something far away now and then.')+P('<b>At night</b> the rods take over: dark adaptation takes about 30 minutes and is lost in seconds by bright light. Use dim red or low white light, look slightly to the side of a faint object (the centre of the eye has no rods), and remember that hypoxia and smoking reduce night vision. Each eye has a blind spot; with two eyes and head movement it is covered.'),
     P('En trafikkonflikt på kollisjonskurs <b>står stille</b> i frontruten; den bare vokser, sakte først og svært fort til slutt. Øyet ser detaljer bare i et lite sentralt område, så <b>scan</b> i sektorer på rundt 10°, med en pause på rundt et sekund på hver (typisk). Uten noe å fokusere på (dis, blå himmel) slapper øynene av til kort fokus (empty-field myopia): fokuser på noe langt unna innimellom.')+P('<b>Om natten</b> tar stavene over: mørketilpasning tar rundt 30 minutter og tapes på sekunder i sterkt lys. Bruk svakt rødt eller svakt hvitt lys, se litt til siden for et svakt objekt (midten av øyet har ingen staver), og husk at hypoksi og røyking svekker nattsynet. Hvert øye har en blind flekk; med to øyne og hodebevegelse dekkes den.'))]]];
function drawDD(){ const open=[...document.querySelectorAll('#ddList details[open]')].map(d=>d.id);
  el('ddList').innerHTML=DD.map(([id,t,s,ps])=>`<details class="dfold" id="dd-${id}"><summary>${L(t)} <small>${L(s)}</small></summary><div>${ps.map(p=>p==='TUC'?tab(TUC):p==='DM'?tab(DM):L(p)).join('')}</div></details>`).join('');
  open.forEach(i=>{ const d=el(i); if(d) d.open=true; }); }

/* ---------------- Test yourself ---------------- */
function drawTake(){ const TK=[
  t2('<b>Attention is a single channel.</b> Multitasking is switching; write down and read back.','<b>Oppmerksomheten er én kanal.</b> Multitasking er å bytte; skriv ned og les tilbake.'),
  t2('<b>Workload peaks at take-off and the approach.</b> Plan and brief in the quiet phases; reduce the task when it is too much.','<b>Arbeidsbelastningen topper seg ved start og innflyging.</b> Planlegg og brief i de rolige fasene; reduser oppgaven når det blir for mye.'),
  t2('<b>Startle costs seconds.</b> Aviate first, then diagnose.','<b>Skvettreaksjon koster sekunder.</b> Fly først, finn feilen etterpå.'),
  t2('<b>Automation:</b> read the modes, know what it is doing, and take a lower level when it surprises you.','<b>Automatikk:</b> les modusene, vit hva den gjør, og gå ned et nivå når den overrasker deg.'),
  t2('<b>TEM:</b> manage threats, trap errors, recover from undesired states: the earlier, the better.','<b>TEM:</b> håndter trusler, fang feil, gjenopprett fra uønskede tilstander: jo tidligere, jo bedre.'),
  t2('<b>CRM:</b> brief, follow SOPs, crosscheck, and speak up clearly, up to "Go around".','<b>CRM:</b> brief, følg SOP-er, kryssjekk, og si tydelig fra, helt til «Go around».'),
  {dp:1,...t2('<b>Decide with a structure</b> (for example FOR-DEC or DODAR) and set decision points in advance.','<b>Bestem med en struktur</b> (for eksempel FOR-DEC eller DODAR) og sett beslutningspunkter på forhånd.')},
  t2('<b>Fatigue</b> comes from hours awake and the body clock (lowest 02–06). 17 h awake ≈ 0.5 ‰ (typical). Sleep before night duties.','<b>Tretthet</b> kommer av timer våken og døgnrytmen (lavest 02–06). 17 t våken ≈ 0,5 ‰ (typisk). Sov før nattjenester.'),
  t2('<b>Alcohol limit 0.2 ‰</b>; check every medicine with an aeromedical examiner. <b>Hypoxia</b> takes your judgement first: mask on at once.','<b>Promillegrense 0,2 ‰</b>; sjekk hver medisin med en flylege. <b>Hypoksi</b> tar vurderingsevnen først: masken på med en gang.')];
  el('take').innerHTML=TK.filter(x=>!x.dp||deepOn()).map(x=>`<li>${L(x)}</li>`).join('');
  const m=el('maid'); m.querySelector('.k').textContent=L(t2('Memory aid','Huskeregel'));
  m.querySelector('b').textContent='IMSAFE';
  m.querySelector('p').textContent=L(t2('Before every flight: Illness, Medication, Stress, Alcohol, Fatigue, Eating (and emotion). If any of them is not right, you are not fit to fly.','Før hver flyging: Illness (sykdom), Medication (medisiner), Stress, Alcohol (alkohol), Fatigue (tretthet), Eating (mat, og følelser). Er noe av dette ikke i orden, er du ikke skikket til å fly.')); }

LAB.quiz(el('qbox'),'humanperf',()=>LAB.shuffle([
 {q:t2('Working memory typically holds about…','Arbeidsminnet holder typisk rundt …'),a:[t2('5–9 items for a short time','5–9 elementer en kort stund'),t2('20–30 items for an hour','20–30 elementer i en time'),t2('1–2 items','1–2 elementer'),t2('unlimited items if you concentrate','ubegrenset hvis du konsentrerer deg')],c:0,e:t2('7 ± 2, and it is easily disrupted: write down, read back.','7 ± 2, og det forstyrres lett: skriv ned, les tilbake.')},
 {q:t2('Performance is best at…','Prestasjonen er best ved …'),a:[t2('a medium level of arousal','middels aktivering'),t2('the highest possible arousal','høyest mulig aktivering'),t2('the lowest possible workload','lavest mulig arbeidsbelastning'),t2('any level, with experience','hvilket som helst nivå, med erfaring')],c:0,e:t2('The inverted U: both underload and overload reduce performance.','Den omvendte U-en: både underbelastning og overbelastning senker prestasjonen.')},
 {q:t2('After a startling event, the first priority is to…','Etter en skvettreaksjon er første prioritet å …'),a:[t2('fly the aircraft','fly flyet'),t2('find the cause','finne årsaken'),t2('call ATC','kalle ATC'),t2('run the checklist','kjøre sjekklisten')],c:0,e:t2('Aviate, navigate, communicate. Diagnosis comes after a stable flight path.','Fly, naviger, kommuniser. Feilsøking kommer etter en stabil flybane.')},
 {q:t2('The autopilot does something you did not expect. Good practice is to…','Autopiloten gjør noe du ikke forventet. God praksis er å …'),a:[t2('read the mode annunciations, and if in doubt take a lower level of automation','lese modusvisningene, og er du i tvil, gå ned et automatikknivå'),t2('reprogram the FMS until it works','programmere FMS på nytt til det virker'),t2('wait and see','vente og se'),t2('switch everything off at once in all cases','slå av alt med en gang i alle tilfeller')],c:0,e:t2('Know what it is doing; if it surprises you, fly it at a level you understand.','Vit hva den gjør; overrasker den deg, fly på et nivå du forstår.')},
 {q:t2('In TEM, an error is…','I TEM er en feil …'),a:[t2('a crew action or inaction that leads to a deviation from intentions or expectations','en handling eller unnlatelse fra besetningen som fører til avvik fra intensjon eller forventning'),t2('an event outside the crew\'s control','en hendelse utenfor besetningens kontroll'),t2('always a violation of the rules','alltid et regelbrudd'),t2('the same as an undesired aircraft state','det samme som en uønsket flytilstand')],c:0,e:t2('Threats come from outside; errors from the crew.','Trusler kommer utenfra; feil fra besetningen.')},
 {q:t2('You find the aircraft in an undesired state (fast and high on the approach). First…','Du finner flyet i en uønsket tilstand (raskt og høyt på innflyging). Først …'),a:[t2('recover the aircraft (here: go around), then deal with the error','gjenopprett flyet (her: go around), så håndter feilen'),t2('find out who made the error','finn ut hvem som gjorde feilen'),t2('continue and fix it on the runway','fortsett og rett det på rullebanen'),t2('report it to ATC','meld det til ATC')],c:0,e:t2('Fly the aircraft first. The analysis can wait.','Fly flyet først. Analysen kan vente.')},
 {q:t2('Which of these is a widely used decision-making model?','Hvilken av disse er en mye brukt beslutningsmodell?'),a:[t2('FOR-DEC: Facts, Options, Risks and benefits, Decision, Execution, Check','FOR-DEC: Fakta, Alternativer, Risiko og nytte, Beslutning, Utførelse, Kontroll'),t2('ATIS: Aviate, Talk, Inform, Sign','ATIS: Aviate, Talk, Inform, Sign'),t2('SOP: Stop, Observe, Proceed','SOP: Stop, Observe, Proceed'),t2('PAPI: Plan, Act, Plan again, Inform','PAPI: Plan, Act, Plan again, Inform')],c:0,e:t2('FOR-DEC and DODAR are two examples; the steps matter more than the name.','FOR-DEC og DODAR er to eksempler; trinnene betyr mer enn navnet.')},
 {q:t2('The window of circadian low is about…','Døgnrytmens bunn er rundt …'),a:[t2('02:00–06:00','02:00–06:00'),t2('12:00–14:00','12:00–14:00'),t2('18:00–22:00','18:00–22:00'),t2('22:00–24:00','22:00–24:00')],c:0,e:t2('EASA defines it as 02:00–05:59 in the time zone you are acclimatised to.','EASA definerer den som 02:00–05:59 i tidssonen du er akklimatisert til.')},
 {q:t2('About 24 hours without sleep impairs performance roughly like a blood alcohol of…','Rundt 24 timer uten søvn svekker prestasjonen omtrent som en promille på …'),a:[t2('1 ‰ (0.10 %)','1 ‰ (0,10 %)'),t2('0.1 ‰','0,1 ‰'),t2('0.2 ‰','0,2 ‰'),t2('no effect','ingen virkning')],c:0,e:t2('Typical figures from a well-known study: 17 h ≈ 0.5 ‰, 24 h ≈ 1 ‰.','Typiske tall fra en kjent studie: 17 t ≈ 0,5 ‰, 24 t ≈ 1 ‰.')},
 {q:t2('The blood alcohol limit for crew in the EU is…','Promillegrensen for besetning i EU er …'),a:[t2('0.2 ‰ (0.2 g/L)','0,2 ‰ (0,2 g/L)'),t2('0.5 ‰','0,5 ‰'),t2('0.8 ‰','0,8 ‰'),t2('there is no limit, only the 8-hour rule','det finnes ingen grense, bare 8-timersregelen')],c:0,e:t2('0.2 g/L, with testing of crews in the EU.','0,2 g/L, med testing av besetninger i EU.')},
 {q:t2('Why is hypoxia so dangerous?','Hvorfor er hypoksi så farlig?'),a:[t2('It impairs judgement before you notice, often with a feeling of well-being','Den svekker vurderingsevnen før du merker det, ofte med en følelse av velvære'),t2('It always starts with severe pain','Den starter alltid med sterke smerter'),t2('It only happens above FL400','Den skjer bare over FL400'),t2('It is easy to recognise in yourself','Den er lett å kjenne igjen hos seg selv')],c:0,e:t2('Insidious: know your symptoms, and put the mask on first.','Snikende: kjenn dine symptomer, og ta masken på først.')},
 {q:t2('A traffic conflict on a collision course…','En trafikkonflikt på kollisjonskurs …'),a:[t2('stays at the same spot on the windscreen and grows','står stille i frontruten og vokser'),t2('moves quickly across the windscreen','beveger seg raskt over frontruten'),t2('is easiest to see in the centre of a blue sky','er lettest å se midt i blå himmel'),t2('always appears large well in advance','alltid ser stor ut i god tid')],c:0,e:t2('No relative movement: scan in sectors so you do not miss it.','Ingen relativ bevegelse: scan i sektorer så du ikke overser den.')}]),10);

/* ---------------- static strings, text, start ---------------- */
LAB.add({},{'Human Performance':'Menneskelig ytelse','Human performance: attention, workload, error and fatigue':'Menneskelig ytelse: oppmerksomhet, arbeidsbelastning, feil og tretthet','Birdbird Virtual Labs · Human factors':'Birdbird Virtual Labs · Menneskelige faktorer',
 '1 · Understand':'1 · Forstå','2 · Explore':'2 · Utforsk','3 · Test yourself':'3 · Test deg selv','Key concepts':'Nøkkelbegreper','Deep dive':'Dypdykk','The human performance lab':'Labben for menneskelig ytelse','Try it':'Prøv selv','Key points':'Det viktigste','Test yourself':'Test deg selv',
 'Controls':'Kontroller','The flight':'Flygingen','The pilot':'Piloten','Sleep':'Søvn','The duty':'Tjenesten','Scenario':'Scenario','Countermeasures':'Mottiltak','Scenarios':'Scenarier','Mode':'Modus','Sections':'Seksjoner',
 'Chart of the demand on your attention against your capacity through a flight, or of your alertness over a day and a night with sleep, the body clock and a duty period.':'Diagram over kravet til oppmerksomheten mot kapasiteten gjennom en flyging, eller over årvåkenheten gjennom et døgn med søvn, døgnrytme og en tjenesteperiode.'});
LAB.tx({lead:'De fleste ulykker skyldes ikke mangel på kunnskap, men en pilot som er overbelastet, overrasket, trøtt eller sikker på feil ting. Se hvor arbeidsbelastningen løper fra kapasiteten, hvordan søvn og døgnrytme sliter deg ned, og hvordan en besetning fanger trusler og feil før de blir en ulykke.'});
function texts(){
  el('kin').textContent=L(t2('The ideas that actually change how you fly. "Show in the model" sets the lab up for you.','Ideene som faktisk endrer hvordan du flyr. «Vis i modellen» setter opp labben for deg.'));
  el('xLead').textContent=L(t2('Pick a mode above the figure. Workload: change the flight and the pilot and watch the margin. Fatigue: plan the sleep and the duty. Threat and error: switch on countermeasures and see where the chain stops.','Velg modus over figuren. Arbeidsbelastning: endre flygingen og piloten og se på marginen. Tretthet: planlegg søvn og tjeneste. Trussel og feil: slå på mottiltak og se hvor kjeden stopper.'));
  el('tryLead').textContent=L(t2('Think first, then check. "Set it up in the model" shows you why.','Tenk først, og sjekk. «Sett det opp i modellen» viser deg hvorfor.'));
  el('foot').innerHTML=L(t2('<b>Model and limitations.</b> Teaching models, not measurements. Workload and capacity are on a relative 0–100 scale with typical shapes for each phase; the effects of weather, briefing, hand-flying, startle and fatigue are illustrative. Alertness follows the two-process idea (sleep pressure rising while awake and falling in sleep, plus a 24-hour body clock lowest in the early morning) with typical time constants; individuals differ a lot. The alcohol comparison uses the often-quoted figures from one study (17 h ≈ 0.05 %, 24 h ≈ 0.10 %). The scenarios are generic examples. Rules quoted are EU (EASA); always follow your operator and authority.','<b>Modell og begrensninger.</b> Undervisningsmodeller, ikke målinger. Arbeidsbelastning og kapasitet er på en relativ skala 0–100 med typiske former for hver fase; virkningen av vær, brief, håndflyging, skvettreaksjon og tretthet er illustrerende. Årvåkenheten følger to-prosess-ideen (søvnpress som øker når du er våken og faller i søvn, pluss en døgnrytme lavest tidlig om morgenen) med typiske tidskonstanter; folk er svært forskjellige. Promillesammenligningen bruker de ofte siterte tallene fra én studie (17 t ≈ 0,05 %, 24 t ≈ 0,10 %). Scenariene er generelle eksempler. Reglene som nevnes er EU (EASA); følg alltid operatøren og myndigheten din.'));
  el('ddH').textContent=L(t2('Deep dive','Dypdykk')); }
function all(){ texts(); drawTabs(); drawPre(); drawTask(); drawDD(); drawTake(); syncCtl(); upd(); }
LAB.onLang(all);
document.addEventListener('labdepth',all);
LAB.start('hp');
setMode('wl'); all();
/* old anchors */
const HM={'#info':'wl','#workload':'wl','#fatigue':'fat','#tem':'tem','#drill':'tem'};
if(HM[location.hash]){ setMode(HM[location.hash]); requestAnimationFrame(()=>el('hpVp').scrollIntoView({block:'start'})); }
if(/^#dd-/.test(location.hash)&&el(location.hash.slice(1))){ const id=location.hash.slice(1); if(depth()==='short') LAB.setDepth('deep'); setTimeout(()=>{ const d=el(id); if(d){ d.open=true; d.scrollIntoView({block:'center'}); } },350); }
if(location.hash==='#vision'){ if(depth()==='short') LAB.setDepth('deep'); setTimeout(()=>{ const d=el('dd-vis'); if(d){ d.open=true; d.scrollIntoView({block:'center'}); } },350); }
})();
